add_action( 'rest_api_init', function() {
    register_rest_route( 'terso/v1', '/affiliates/(?P<id>\d+)/payout', array(
        'methods'             => WP_REST_Server::CREATABLE,
        'callback'            => array( 'Terso_Payout_Controller', 'process_payout' ),
        'permission_callback' => function( $request ) {
            if ( ! current_user_can( 'manage_options' ) ) {
                return new WP_Error( 'rest_forbidden', esc_html__( 'Insufficient permissions.', 'terso-studio' ), array( 'status' => 403 ) );
            }
            return true;
        },
        'args'                => array(
            'amount' => array(
                'required'          => true,
                'type'              => 'number',
                'validate_callback' => function( $param, $request, $key ) {
                    return is_numeric( $param ) && $param > 0;
                },
                'sanitize_callback' => 'floatval',
            ),
        ),
    ) );
} );

public function get_affiliate_stats( WP_REST_Request $request ) {
    $affiliate_id = absint( $request->get_param( 'id' ) );
    $stats = $this->stats_service->get_for_affiliate( $affiliate_id );

    if ( ! $stats ) {
        return new WP_Error( 'not_found', esc_html__( 'Affiliate not found.', 'terso-studio' ), array( 'status' => 404 ) );
    }

    return new WP_REST_Response( array(
        'success' => true,
        'data'    => $stats,
    ), 200 );
}
